#include <vector>
#include <cstddef>
#include <algorithm>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    int globalMax = 0;

    #pragma omp parallel
    {
        int localMax = 0;

        #pragma omp for nowait
        for (std::size_t i = 0; i < N; ++i) {
            int deg = 0;
            const std::size_t rowBase = i * N;
            for (std::size_t j = 0; j < N; ++j) {
                deg += (A[rowBase + j] != 0) ? 1 : 0;
            }
            localMax = std::max(localMax, deg);
        }

        #pragma omp critical
        {
            globalMax = std::max(globalMax, localMax);
        }
    }

    return globalMax;
}
